CREATE OR REPLACE FUNCTION public.accept_invite_code(p_code text, p_display_name text, p_nickname text DEFAULT NULL::text, p_relation text DEFAULT '가족'::text)
 RETURNS TABLE(baby_id uuid, invite_type text, permission_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite public.invite_codes;
  v_friendship public.user_friendships;
  v_relation public.relationship_label;
  v_name text := btrim(coalesce(p_display_name, ''));
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if v_name = '' then
    raise exception 'display name required' using errcode = '22023';
  end if;

  select * into v_invite
  from public.invite_codes ic
  where ic.code = upper(btrim(p_code))
  for update;
  if not found then raise exception 'invalid invite code' using errcode = 'P0002'; end if;
  if v_invite.created_by = auth.uid() then raise exception 'cannot accept your own invite' using errcode = '22023'; end if;
  if v_invite.revoked_at is not null then raise exception 'invite revoked' using errcode = '22023'; end if;
  if v_invite.expires_at is not null and v_invite.expires_at <= now() then raise exception 'invite expired' using errcode = '22023'; end if;
  if v_invite.used_count >= v_invite.max_uses then raise exception 'invite already used' using errcode = '22023'; end if;

  -- Bearer invite codes cannot outlive the issuer's authority. This also makes
  -- any code forged through the former NULL fail-open guard unusable.
  if v_invite.invite_type in ('family', 'baby_friend') then
    if v_invite.baby_id is null or v_invite.created_by is null then
      raise exception 'invite issuer no longer has permission' using errcode = '42501';
    end if;

    -- Hold the issuer membership row through the grant. A concurrent removal
    -- or demotion must not race between authorization and membership insert.
    perform 1
    from public.baby_members issuer
    where issuer.baby_id = v_invite.baby_id
      and issuer.user_id = v_invite.created_by
      and issuer.status = 'active'
      and issuer.permission_role = 'admin'::public.permission_role
    for update;
    if not found then
      raise exception 'invite issuer no longer has permission' using errcode = '42501';
    end if;
  end if;

  begin
    v_relation := coalesce(
      nullif(btrim(p_relation), ''),
      v_invite.relationship_label::text
    )::public.relationship_label;
  exception when invalid_text_representation then
    raise exception 'invalid relationship' using errcode = '22023';
  end;

  update public.profiles p
  set display_name = v_name,
      nickname = nullif(btrim(p_nickname), ''),
      default_relation = case
        when v_invite.invite_type = 'family' then v_relation::text
        else p.default_relation
      end,
      updated_at = now()
  where p.id = auth.uid();

  if v_invite.invite_type = 'family' then
    if exists (
      select 1 from public.baby_members bm
      where bm.baby_id = v_invite.baby_id
        and bm.user_id = auth.uid()
        and bm.status = 'active'
    ) then raise exception 'already connected to this baby' using errcode = '23505'; end if;

    insert into public.baby_members (
      baby_id, user_id, permission_role, relationship_label, status, display_name_override
    ) values (
      v_invite.baby_id, auth.uid(), v_invite.permission_role, v_relation, 'active', v_name
    );
  elsif v_invite.invite_type = 'baby_friend' then
    insert into public.memory_friends (baby_id, user_id, invited_by, status)
    values (v_invite.baby_id, auth.uid(), v_invite.created_by, 'active')
    on conflict on constraint memory_friends_baby_id_user_id_key do update
      set status = 'active', invited_by = excluded.invited_by, updated_at = now();
  else
    select * into v_friendship
    from public.user_friendships uf
    where (uf.requester_id = v_invite.created_by and uf.receiver_id = auth.uid())
       or (uf.requester_id = auth.uid() and uf.receiver_id = v_invite.created_by)
    for update;

    if found and v_friendship.status = 'blocked' then
      raise exception 'friendship is blocked' using errcode = '42501';
    elsif found then
      update public.user_friendships uf
      set status = 'accepted', accepted_at = now(), blocked_at = null
      where uf.id = v_friendship.id;
    else
      insert into public.user_friendships (
        requester_id, receiver_id, status, accepted_at
      ) values (
        v_invite.created_by, auth.uid(), 'accepted', now()
      );
    end if;
  end if;

  update public.invite_codes ic
  set used_count = ic.used_count + 1, used_by = auth.uid(), used_at = now()
  where ic.id = v_invite.id;

  return query select
    v_invite.baby_id,
    v_invite.invite_type,
    case when v_invite.invite_type = 'family'
      then v_invite.permission_role::text
      else v_invite.invite_type
    end;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_darin_friend_to_baby(p_baby_id uuid, p_friend_user_id uuid)
 RETURNS memory_friends
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.memory_friends;
begin
  if auth.uid() is null
     or public.baby_permission(p_baby_id)
        is distinct from 'admin'::public.permission_role then
    raise exception 'only baby admin can invite memory friends' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public.user_friendships uf
    where uf.status = 'accepted'
      and (
        (uf.requester_id = auth.uid() and uf.receiver_id = p_friend_user_id)
        or (uf.receiver_id = auth.uid() and uf.requester_id = p_friend_user_id)
      )
  ) then
    raise exception 'accepted Darin friendship required' using errcode = '42501';
  end if;

  insert into public.memory_friends (baby_id, user_id, invited_by, status)
  values (p_baby_id, p_friend_user_id, auth.uid(), 'active')
  on conflict (baby_id, user_id) do update
    set invited_by = auth.uid(), status = 'active', updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.baby_member_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.permission_role is distinct from old.permission_role
     and public.baby_permission(old.baby_id) is distinct from 'admin' then
    raise exception 'only baby admin can change member roles'
      using errcode = '42501';
  end if;
  if new.user_id is distinct from old.user_id or new.baby_id is distinct from old.baby_id then
    raise exception 'baby member identity is immutable';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_invite_code(p_baby_id uuid, p_invite_type text, p_role text DEFAULT 'editor'::text, p_relation text DEFAULT '가족'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_max_uses integer DEFAULT 1)
 RETURNS invite_codes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_invite public.invite_codes;
  v_relation public.relationship_label;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_invite_type not in ('family', 'baby_friend', 'darin_friend') then
    raise exception 'invalid invite type' using errcode = '22023';
  end if;
  if p_invite_type <> 'darin_friend'
     and (
       p_baby_id is null
       or public.baby_permission(p_baby_id)
          is distinct from 'admin'::public.permission_role
     ) then
    raise exception 'only baby admin can create baby invites' using errcode = '42501';
  end if;
  if p_invite_type = 'family' and p_role not in ('admin', 'editor') then
    raise exception 'family role must be admin or editor' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= now() then
    raise exception 'invite expiration must be in the future' using errcode = '22023';
  end if;
  if coalesce(p_max_uses, 1) < 1 then
    raise exception 'max uses must be positive' using errcode = '22023';
  end if;

  begin
    v_relation := coalesce(
      nullif(btrim(p_relation), ''),
      case when p_invite_type = 'family' then '가족' else '친구' end
    )::public.relationship_label;
  exception when invalid_text_representation then
    raise exception 'invalid relationship' using errcode = '22023';
  end;

  loop
    v_code := 'DARIN-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    begin
      insert into public.invite_codes (
        baby_id, code, created_by, invite_type, permission_role,
        relationship_label, expires_at, max_uses, used_count
      ) values (
        case when p_invite_type = 'darin_friend' then null else p_baby_id end,
        v_code,
        auth.uid(),
        p_invite_type,
        case when p_invite_type = 'family'
          then p_role::public.permission_role
          else 'viewer'::public.permission_role
        end,
        v_relation,
        p_expires_at,
        p_max_uses,
        0
      ) returning * into v_invite;
      return v_invite;
    exception when unique_violation then
      -- Only a generated-code collision is retried.
    end;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.diary_entry_identity_unchanged()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.id <> old.id
    or new.baby_id <> old.baby_id
    or new.author_id <> old.author_id
    or new.client_generated_id is distinct from old.client_generated_id
    or new.created_at <> old.created_at then
    raise exception 'diary entry identity columns are immutable';
  end if;
  if old.deleted_at is not null and new.deleted_at is distinct from old.deleted_at then
    raise exception 'deleted diary entries are immutable';
  end if;
  if old.deleted_at is null and new.deleted_at is not null
    and not public.can_manage_diary_entry(old.id) then
    raise exception 'diary entry delete permission denied';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.growth_book_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.id <> old.id or new.baby_id <> old.baby_id or new.created_by <> old.created_by
    or new.created_at <> old.created_at then
    raise exception 'growth book identity columns are immutable';
  end if;
  if old.deleted_at is not null and new is distinct from old then
    raise exception 'deleted growth books are immutable';
  end if;
  if old.deleted_at is null and new.deleted_at is not null
    and public.baby_permission(old.baby_id) <> 'admin' then
    raise exception 'growth book delete permission denied' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.growth_book_page_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.id <> old.id or new.growth_book_id <> old.growth_book_id
    or new.baby_id <> old.baby_id or new.created_by <> old.created_by
    or new.created_at <> old.created_at then
    raise exception 'growth book page identity columns are immutable';
  end if;
  if old.deleted_at is not null and new is distinct from old then
    raise exception 'deleted growth book pages are immutable';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.memory_post_identity_unchanged()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.id <> old.id
    or new.baby_id <> old.baby_id
    or new.author_id <> old.author_id
    or new.created_at <> old.created_at then
    raise exception 'memory post identity columns are immutable';
  end if;
  if new.deleted_at is distinct from old.deleted_at
    and not public.can_delete_memory_post(old.id) then
    raise exception 'memory post delete permission denied';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_darin_id_invite_request(p_request_id uuid, p_accept boolean)
 RETURNS TABLE(baby_id uuid, request_type text, permission_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_request public.darin_invite_requests;
  v_response_status text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select request_row.* into v_request
  from public.darin_invite_requests as request_row
  where request_row.id = p_request_id
    and request_row.receiver_id = auth.uid()
    and request_row.status = 'pending'
  for update;
  if not found then raise exception 'invite request unavailable' using errcode = 'P0002'; end if;
  if v_request.expires_at <= now() then
    raise exception 'invite request expired' using errcode = '22023';
  end if;

  v_response_status := case when p_accept then 'accepted' else 'declined' end;
  if p_accept then
    if v_request.request_type = 'family' then
      insert into public.baby_members (
        baby_id, user_id, permission_role, relationship_label, status, display_name_override
      ) values (
        v_request.baby_id, auth.uid(), v_request.permission_role,
        v_request.relationship_label, 'active', null
      ) on conflict on constraint baby_members_baby_id_user_id_key do update
        set permission_role = excluded.permission_role,
            relationship_label = excluded.relationship_label,
            status = 'active';
    else
      insert into public.memory_friends (baby_id, user_id, invited_by, status)
      values (v_request.baby_id, auth.uid(), v_request.sender_id, 'active')
      on conflict on constraint memory_friends_baby_id_user_id_key do update
        set status = 'active', invited_by = excluded.invited_by;
    end if;

    insert into public.notification_events (
      recipient_id, actor_id, baby_id, event_type, title, body, data, dedupe_key, status
    ) values (
      v_request.sender_id,
      auth.uid(),
      v_request.baby_id,
      'family_joined',
      case when v_request.request_type = 'family' then '가족 초대가 수락됐어요' else '친구 요청이 수락됐어요' end,
      case when v_request.request_type = 'family' then '새 공유 멤버가 연결됐어요.' else '친구 공개 순간을 함께 볼 수 있어요.' end,
      jsonb_build_object('requestId', v_request.id, 'requestType', v_request.request_type, 'route', 'family'),
      'darin-invite-response:' || v_request.id::text,
      'pending'
    ) on conflict (recipient_id, dedupe_key) where dedupe_key is not null do nothing;
  else
    insert into public.notification_events (
      recipient_id, actor_id, baby_id, event_type, title, body, data, dedupe_key, status
    ) values (
      v_request.sender_id,
      auth.uid(),
      v_request.baby_id,
      'invite_declined',
      '초대 요청이 수락되지 않았어요',
      '필요하면 새 초대를 보낼 수 있어요.',
      jsonb_build_object('requestId', v_request.id, 'requestType', v_request.request_type, 'route', 'family'),
      'darin-invite-response:' || v_request.id::text,
      'pending'
    ) on conflict (recipient_id, dedupe_key) where dedupe_key is not null do nothing;
  end if;

  update public.darin_invite_requests as request_row
  set status = v_response_status, responded_at = now()
  where request_row.id = v_request.id;

  update public.notification_events as event_row
  set read_at = now(),
      data = jsonb_set(event_row.data, '{requestStatus}', to_jsonb(v_response_status), true)
  where event_row.recipient_id = auth.uid()
    and event_row.event_type = 'invite_request'
    and event_row.data->>'requestId' = v_request.id::text;

  return query select v_request.baby_id, v_request.request_type, v_request.permission_role::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_darin_id_invite_request(p_baby_id uuid, p_darin_id text, p_request_type text, p_role text DEFAULT 'editor'::text, p_relation text DEFAULT '가족'::text)
 RETURNS TABLE(request_id uuid, recipient_nickname text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_receiver public.profiles;
  v_request public.darin_invite_requests;
  v_role public.permission_role;
  v_relation public.relationship_label;
begin
  if auth.uid() is null
     or public.baby_permission(p_baby_id) is distinct from 'admin'::public.permission_role then
    raise exception 'only baby admin can send requests' using errcode = '42501';
  end if;
  if p_request_type not in ('family', 'friend') then
    raise exception 'invalid request type' using errcode = '22023';
  end if;

  select * into v_receiver
  from public.profiles
  where lower(darin_id) = lower(btrim(p_darin_id));
  if not found then raise exception 'Darin ID not found' using errcode = 'P0002'; end if;
  if v_receiver.id = auth.uid() then raise exception 'cannot invite yourself' using errcode = '22023'; end if;

  if p_request_type = 'family' then
    if p_role not in ('admin', 'editor') then
      raise exception 'invalid family role' using errcode = '22023';
    end if;
    v_role := p_role::public.permission_role;
    v_relation := coalesce(nullif(btrim(p_relation), ''), '가족')::public.relationship_label;
  else
    v_role := 'viewer';
    v_relation := '친구';
  end if;

  if (p_request_type = 'family' and exists (
    select 1 from public.baby_members
    where baby_id = p_baby_id and user_id = v_receiver.id and status = 'active'
  )) or (p_request_type = 'friend' and exists (
    select 1 from public.memory_friends
    where baby_id = p_baby_id and user_id = v_receiver.id and status = 'active'
  )) then
    raise exception 'already connected' using errcode = '23505';
  end if;

  update public.darin_invite_requests
  set status = 'cancelled', responded_at = now()
  where baby_id = p_baby_id
    and sender_id = auth.uid()
    and receiver_id = v_receiver.id
    and request_type = p_request_type
    and status = 'pending'
    and expires_at <= now();

  if exists (
    select 1 from public.darin_invite_requests
    where baby_id = p_baby_id
      and sender_id = auth.uid()
      and receiver_id = v_receiver.id
      and request_type = p_request_type
      and status = 'pending'
      and expires_at > now()
  ) then
    raise exception 'invite request already pending' using errcode = '23505';
  end if;

  insert into public.darin_invite_requests (
    baby_id, sender_id, receiver_id, request_type, permission_role,
    relationship_label, expires_at
  ) values (
    p_baby_id, auth.uid(), v_receiver.id, p_request_type, v_role,
    v_relation, now() + interval '30 days'
  ) returning * into v_request;

  insert into public.notification_events (
    recipient_id, actor_id, baby_id, event_type, title, body, data, dedupe_key, status
  ) values (
    v_receiver.id,
    auth.uid(),
    p_baby_id,
    'invite_request',
    case when p_request_type = 'family' then '가족 초대 요청' else '친구 추가 요청' end,
    (select coalesce(display_name, '돌봄 멤버') from public.profiles where id = auth.uid()) || '님이 요청을 보냈어요.',
    jsonb_build_object(
      'requestId', v_request.id,
      'requestType', p_request_type,
      'requestStatus', 'pending',
      'route', 'family'
    ),
    'darin-invite:' || v_request.id::text,
    'pending'
  );

  return query select v_request.id, v_receiver.display_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_diary_entry(p_diary_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_manage_diary_entry(p_diary_entry_id) then
    raise exception 'diary entry not found or delete permission denied';
  end if;
  update public.diary_entries
  set deleted_at = now()
  where id = p_diary_entry_id
    and deleted_at is null;
  if not found then
    raise exception 'diary entry not found or delete permission denied';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_growth_book(p_growth_book_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.growth_books b where b.id = p_growth_book_id
      and b.deleted_at is null and public.baby_permission(b.baby_id) = 'admin'
  ) then raise exception 'growth book not found or delete permission denied' using errcode = '42501'; end if;
  update public.growth_books set deleted_at = now() where id = p_growth_book_id and deleted_at is null;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_growth_book_page(p_page_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1 from public.growth_book_pages p join public.growth_books b on b.id = p.growth_book_id
    where p.id = p_page_id and p.deleted_at is null and b.deleted_at is null
      and public.baby_permission(p.baby_id) in ('admin', 'editor')
  ) then raise exception 'growth book page not found or delete permission denied' using errcode = '42501'; end if;
  update public.growth_book_pages set deleted_at = now() where id = p_page_id and deleted_at is null;
end;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_memory_post(p_memory_post_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  affected_rows integer;
begin
  if not public.can_delete_memory_post(p_memory_post_id) then
    raise exception 'memory post not found or delete permission denied'
      using errcode = '42501';
  end if;

  update public.memory_posts
  set deleted_at = now()
  where id = p_memory_post_id
    and deleted_at is null;

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    raise exception 'memory post not found or delete permission denied'
      using errcode = '42501';
  end if;
end;
$function$
